-- 客服知识库增量扩展：只追加常用答案，不修改既有业务表或历史数据。
INSERT OR IGNORE INTO customer_service_knowledge(id,group_key,title,keywords,answer,priority,enabled) VALUES
  (101,'purchase','幼宠选购建议','幼犬,幼猫,新手,适合,推荐','可以的。为了给您更准确的建议，请告诉我宠物类型、年龄、预计体型、家庭是否有儿童或其他宠物，以及您的预算。我会结合健康档案、性格和饲养难度帮您筛选。',120,1),
  (102,'purchase','价格与费用说明','价格,多少钱,费用,优惠,定金','商品页显示的是当前实时价格。下单前请同时核对健康保障、运输方式和售后范围；如涉及优惠或特殊费用，我会请客服经理结合具体商品进一步确认。',115,1),
  (103,'order','订单状态说明','待付款,已支付,订单状态,修改订单,取消订单','请发送当前页面中的订单卡片，我会根据订单号核对付款和处理状态。已进入履约流程的订单如需修改或取消，会自动请订单客服经理确认。',120,1),
  (104,'order','支付异常处理','支付失败,重复支付,扣款,未到账,付款失败','请不要重复付款。您可以发送订单卡片并说明支付时间；涉及重复扣款或到账异常时，系统会自动转接订单客服经理核对支付记录。',118,1),
  (105,'after_sale','退款换货流程','退款,退货,换货,售后,赔偿','退款、退货和换货需要结合订单状态、商品情况及平台规则核验。请发送订单卡片并简要说明原因，系统会自动交给售后客服经理继续处理。',125,1),
  (106,'after_sale','投诉处理说明','投诉,不满意,欺骗,曝光,消协','您的反馈会被完整保留并进入专门处理流程。请说明订单、问题经过和期望方案，系统会自动转接售后客服经理；请勿在聊天中发送银行卡或证件完整号码。',130,1),
  (107,'pet_health','常见消化不适','呕吐,腹泻,拉稀,不吃,没精神','请补充宠物品种、年龄、体重、症状开始时间、频率、是否进食饮水和近期饮食变化。线上建议不能替代兽医诊断；持续呕吐、便血、明显脱水或精神异常时请立即就近就医。',125,1),
  (108,'pet_health','疫苗驱虫咨询','疫苗,驱虫,免疫,狂犬','疫苗和驱虫安排需要结合年龄、既往记录、体重和健康状态。请发送商品或宠物档案；如出现发热、过敏、持续精神不振等情况，请尽快联系兽医。',118,1),
  (109,'logistics','发货时效','什么时候发货,发货,多久到,配送','请发送物流订单卡片，我会核对当前履约节点。活体或特殊商品的配送还会受健康检查、天气和承运条件影响，异常延误会自动请物流客服经理处理。',120,1),
  (110,'logistics','物流异常','停滞,丢件,破损,拒收,联系不上','如果物流长时间没有更新、出现破损或无法联系承运方，请发送订单卡片和最新节点，系统会自动转接物流客服经理核查。',122,1),
  (111,'official','隐私与资料安全','身份证,银行卡,隐私,验证码,密码','为了保护您的账户安全，请不要在聊天中发送完整身份证号、银行卡号、支付密码或短信验证码。客服不会索要这些敏感信息。',130,1),
  (112,'official','客服经理接续','经理,人工,真人,复杂问题,无法解决','您可以继续在当前网站窗口描述问题，不需要跳转其他软件。系统会保留上下文，并在 AI 无法确认或遇到高风险问题时自动请对应客服经理接续。',120,1);
